#!/usr/bin/env python3
"""
JSON TUI Viewer - A simple terminal UI for viewing JSON files
"""

import json
import sys
import os
from typing import Any, Dict, List, Union, Optional
from dataclasses import dataclass
from enum import Enum

class Color:
    """ANSI color codes"""
    RESET = "\033[39m\033[49m"
    BLUE = "\033[94m"
    GREEN = "\033[92m"
    CYAN = "\033[96m"
    YELLOW = "\033[93m"
    RED = "\033[91m"
    BOLD = "\033[1m"
    UNBOLD = "\033[22m"
    DIM = "\033[90m"

    # Color + background resets
    FG_RESET = "\033[39m"
    BG_RESET = "\033[49m"

class JSONFormatter:
    """Formats JSON with colors and indentation"""

    def __init__(self):
        self.indent_level = 0
        self.indent_str = "  "

    def format_value(self, value: Any, inline: bool = False) -> str:
        """Format a single JSON value with colors"""
        if value is None:
            return f"{Color.RED}{Color.BG_RESET}null{Color.FG_RESET}{Color.BG_RESET}"
        elif isinstance(value, bool):
            bool_str = "true" if value else "false"
            return f"{Color.YELLOW}{Color.BG_RESET}{bool_str}{Color.FG_RESET}{Color.BG_RESET}"
        elif isinstance(value, (int, float)):
            return f"{Color.CYAN}{Color.BG_RESET}{value}{Color.FG_RESET}{Color.BG_RESET}"
        elif isinstance(value, str):
            return f'{Color.GREEN}{Color.BG_RESET}"{value}"{Color.FG_RESET}{Color.BG_RESET}'
        elif isinstance(value, (list, dict)):
            # For containers, just return the bracket
            if isinstance(value, list):
                return f"{Color.BOLD}[...]{Color.UNBOLD}"
            else:
                return f"{Color.BOLD}{{{Color.UNBOLD}"
        return str(value)

    def format_key(self, key: str) -> str:
        """Format a JSON key with color"""
        return f'{Color.BLUE}{Color.BG_RESET}"{key}"{Color.FG_RESET}{Color.BG_RESET}'

    def format_json(self, obj: Any, current_depth: int = 0) -> str:
        """Recursively format JSON object"""
        if obj is None:
            return f"{Color.RED}{Color.BG_RESET}null{Color.FG_RESET}{Color.BG_RESET}"
        elif isinstance(obj, bool):
            bool_str = "true" if obj else "false"
            return f"{Color.YELLOW}{Color.BG_RESET}{bool_str}{Color.FG_RESET}{Color.BG_RESET}"
        elif isinstance(obj, (int, float)):
            return f"{Color.CYAN}{Color.BG_RESET}{obj}{Color.FG_RESET}{Color.BG_RESET}"
        elif isinstance(obj, str):
            return f'{Color.GREEN}{Color.BG_RESET}"{obj}"{Color.FG_RESET}{Color.BG_RESET}'
        elif isinstance(obj, list):
            return self.format_array(obj, current_depth)
        elif isinstance(obj, dict):
            return self.format_object(obj, current_depth)
        else:
            return str(obj)

    def format_array(self, arr: List, current_depth: int) -> str:
        """Format a JSON array"""
        if not arr:
            return "[]"

        # Check if this is a table (array of similar objects)
        is_table = self.is_table(arr)

        lines = [f"{Color.BOLD}[{Color.UNBOLD}"]
        if is_table:
            lines[0] += f"   {Color.DIM}{Color.BG_RESET}(table view){Color.FG_RESET}{Color.BG_RESET}"

        for i, item in enumerate(arr):
            indent = self.indent_str * (current_depth + 1)
            formatted_item = self.format_json(item, current_depth + 1)
            comma = "," if i < len(arr) - 1 else ""
            lines.append(f"{indent}{formatted_item}{comma}")

        lines.append(f"{self.indent_str * current_depth}]")
        return "\n".join(lines)

    def format_object(self, obj: Dict, current_depth: int) -> str:
        """Format a JSON object"""
        if not obj:
            return "{}"

        lines = ["{"]

        # Sort keys alphabetically
        keys = sorted(obj.keys())

        for i, key in enumerate(keys):
            value = obj[key]
            indent = self.indent_str * (current_depth + 1)
            formatted_key = self.format_key(key)

            if isinstance(value, (dict, list)) and value:
                # Show collapsed form for nested structures
                if isinstance(value, dict):
                    formatted_value = f"{Color.BOLD}{{{Color.UNBOLD}"
                    if len(keys) > 2 and current_depth > 0:
                        formatted_value += "..."
                    formatted_value += f"{Color.BOLD}}}{Color.UNBOLD}"
                else:
                    formatted_value = f"{Color.BOLD}[...]{Color.UNBOLD}"
            else:
                formatted_value = self.format_value(value)

            comma = "," if i < len(keys) - 1 else ""
            lines.append(f"{indent}{formatted_key}: {formatted_value}{comma}")

        lines.append(f"{self.indent_str * current_depth}}}")
        return "\n".join(lines)

    @staticmethod
    def is_table(arr: List) -> bool:
        """Check if array looks like a table (array of similar objects)"""
        if not arr or not isinstance(arr[0], dict):
            return False

        # Check if all items are objects with the same keys
        first_keys = set(arr[0].keys())
        for item in arr[1:]:
            if not isinstance(item, dict) or set(item.keys()) != first_keys:
                return False

        return len(arr) > 1 and len(first_keys) > 0

def main():
    # TODO: Implement TUI interaction
    pass

if __name__ == "__main__":
    main()
EOF
