// JSON Value types
enum class JsonType {
    Null,
    Bool,
    Number,
    String,
    Array,
    Object
};

struct JsonValue;
using JsonObject = std::map<std::string, std::shared_ptr<JsonValue>>;
using JsonArray = std::vector<std::shared_ptr<JsonValue>>;

struct JsonValue {
    JsonType type;
    bool bool_value;
    double number_value;
    std::string string_value;
    JsonArray array_value;
    JsonObject object_value;

    JsonValue() : type(JsonType::Null), bool_value(false), number_value(0) {}
};

// Simple JSON parser
class JsonParser {
public:
    std::shared_ptr<JsonValue> parse(const std::string& json_str) {
        pos = 0;
        input = json_str;
        return parseValue();
    }

private:
    std::string input;
    size_t pos = 0;

    void skipWhitespace() {
        while (pos < input.size() && std::isspace(input[pos])) {
            pos++;
        }
    }

    char peek() {
        skipWhitespace();
        if (pos >= input.size()) return '\0';
        return input[pos];
    }

    char consume() {
        skipWhitespace();
        if (pos >= input.size()) return '\0';
        return input[pos++];
    }

    std::shared_ptr<JsonValue> parseValue() {
        auto val = std::make_shared<JsonValue>();
        char c = peek();

        if (c == 'n') {
            // null
            pos += 4; // skip "null"
            val->type = JsonType::Null;
        } else if (c == 't' || c == 'f') {
            // boolean
            if (c == 't') {
                pos += 4; // skip "true"
                val->bool_value = true;
            } else {
                pos += 5; // skip "false"
                val->bool_value = false;
            }
            val->type = JsonType::Bool;
        } else if (c == '"') {
            // string
            val->string_value = parseString();
            val->type = JsonType::String;
        } else if (c == '[') {
            // array
            val->type = JsonType::Array;
            consume(); // [
            skipWhitespace();
            if (peek() != ']') {
                while (true) {
                    val->array_value.push_back(parseValue());
                    skipWhitespace();
                    if (peek() == ']') break;
                    consume(); // comma
                }
            }
            consume(); // ]
        } else if (c == '{') {
            // object
            val->type = JsonType::Object;
            consume(); // {
            skipWhitespace();
            if (peek() != '}') {
                while (true) {
                    std::string key = parseString();
                    consume(); // :
                    auto value = parseValue();
                    val->object_value[key] = value;
                    skipWhitespace();
                    if (peek() == '}') break;
                    consume(); // comma
                }
            }
            consume(); // }
        } else if (c == '-' || std::isdigit(c)) {
            // number
            val->type = JsonType::Number;
            val->number_value = parseNumber();
        }

        return val;
    }

    std::string parseString() {
        consume(); // opening quote
        std::string result;
        while (pos < input.size() && input[pos] != '"') {
            if (input[pos] == '\\') {
                pos++;
                if (pos < input.size()) {
                    switch (input[pos]) {
                        case 'n': result += '\n'; break;
                        case 't': result += '\t'; break;
                        case 'r': result += '\r'; break;
                        case '"': result += '"'; break;
                        case '\\': result += '\\'; break;
                        case '/': result += '/'; break;
                        default: result += input[pos]; break;
                    }
                    pos++;
                }
            } else {
                result += input[pos++];
            }
        }
        if (pos < input.size()) pos++; // closing quote
        return result;
    }

    double parseNumber() {
        size_t start = pos;
        if (input[pos] == '-') pos++;
        while (pos < input.size() && std::isdigit(input[pos])) pos++;
        if (pos < input.size() && input[pos] == '.') {
            pos++;
            while (pos < input.size() && std::isdigit(input[pos])) pos++;
        }
        if (pos < input.size() && (input[pos] == 'e' || input[pos] == 'E')) {
            pos++;
            if (pos < input.size() && (input[pos] == '+' || input[pos] == '-')) pos++;
            while (pos < input.size() && std::isdigit(input[pos])) pos++;
        }
        return std::stod(input.substr(start, pos - start));
    }
};

class JsonRenderer {
public:
    void render(const std::shared_ptr<JsonValue>& value) {
        current_line = "";
        indent_level = 0;
        output_lines.clear();
        renderValue(value, 0, false);
    }

    void printOutput() {
        for (const auto& line : output_lines) {
            std::cout << line << "\r\n";
        }
    }

private:
    std::vector<std::string> output_lines;
    std::string current_line;
    int indent_level = 0;

    std::string getIndent(int level) {
        return std::string(level * 2, ' ');
    }

    void renderValue(const std::shared_ptr<JsonValue>& val, int depth, bool in_array) {
        if (!val) return;

        switch (val->type) {
            case JsonType::Null:
                current_line += std::string(COLOR_RED) + BG_RESET + "null" + COLOR_RESET + BG_RESET;
                break;
            case JsonType::Bool:
                if (val->bool_value) {
                    current_line += std::string(COLOR_YELLOW) + BG_RESET + "true" + COLOR_RESET + BG_RESET;
                } else {
                    current_line += std::string(COLOR_YELLOW) + BG_RESET + "false" + COLOR_RESET + BG_RESET;
                }
                break;
            case JsonType::Number: {
                char buf[32];
                if (val->number_value == (long long)val->number_value) {
                    snprintf(buf, sizeof(buf), "%lld", (long long)val->number_value);
                } else {
                    snprintf(buf, sizeof(buf), "%g", val->number_value);
                }
                current_line += std::string(COLOR_CYAN) + BG_RESET + buf + COLOR_RESET + BG_RESET;
                break;
            }
            case JsonType::String:
                current_line += std::string(COLOR_GREEN) + BG_RESET + "\"" + val->string_value + "\"" + COLOR_RESET + BG_RESET;
                break;
            case JsonType::Array:
                renderArray(val, depth);
                break;
            case JsonType::Object:
                renderObject(val, depth);
                break;
        }
    }

    void renderArray(const std::shared_ptr<JsonValue>& val, int depth) {
        if (val->array_value.empty()) {
            current_line += "[]";
            return;
        }

        // Check if this is a table
        bool is_table = isTable(val->array_value);

        current_line += std::string(COLOR_BOLD) + "[" + COLOR_UNBOLD;
        if (is_table) {
            current_line += "   " + std::string(COLOR_DIM) + BG_RESET + "(table view)" + COLOR_RESET + BG_RESET;
        }
        output_lines.push_back(current_line);
        current_line = "";

        for (size_t i = 0; i < val->array_value.size(); i++) {
            current_line = getIndent(depth + 1);
            renderValue(val->array_value[i], depth + 1, true);

            if (i < val->array_value.size() - 1) {
                current_line += ",";
            }
            output_lines.push_back(current_line);
            current_line = "";
        }

        current_line = getIndent(depth) + "]";
    }

    void renderObject(const std::shared_ptr<JsonValue>& val, int depth) {
        if (val->object_value.empty()) {
            current_line += "{}";
            return;
        }

        current_line += "{";
        output_lines.push_back(current_line);
        current_line = "";

        // Sort keys alphabetically
        std::vector<std::string> keys;
        for (const auto& kv : val->object_value) {
            keys.push_back(kv.first);
        }
        std::sort(keys.begin(), keys.end());

        for (size_t i = 0; i < keys.size(); i++) {
            const auto& key = keys[i];
            const auto& value = val->object_value.at(key);

            current_line = getIndent(depth + 1);
            current_line += std::string(COLOR_BLUE) + BG_RESET + "\"" + key + "\"" + COLOR_RESET + BG_RESET + ": ";

            if (value->type == JsonType::Object && !value->object_value.empty()) {
                // Collapse nested objects
                current_line += std::string(COLOR_BOLD) + "{" + COLOR_UNBOLD;
                if (depth > 0 || keys.size() > 2) {
                    current_line += "...";
                }
                current_line += std::string(COLOR_BOLD) + "}" + COLOR_UNBOLD;
            } else if (value->type == JsonType::Array && !value->array_value.empty()) {
                // Collapse arrays
                current_line += std::string(COLOR_BOLD) + "[...]" + COLOR_UNBOLD;
            } else {
                renderValue(value, depth + 1, false);
            }

            if (i < keys.size() - 1) {
                current_line += ",";
            }
            output_lines.push_back(current_line);
            current_line = "";
        }

        current_line = getIndent(depth) + "}";
    }

    bool isTable(const JsonArray& arr) {
        if (arr.empty() || arr[0]->type != JsonType::Object) {
            return false;
        }

        const auto& first_obj = arr[0]->object_value;
        for (size_t i = 1; i < arr.size(); i++) {
            if (arr[i]->type != JsonType::Object) {
                return false;
            }
            if (arr[i]->object_value.size() != first_obj.size()) {
                return false;
            }
            for (const auto& kv : first_obj) {
                if (arr[i]->object_value.find(kv.first) == arr[i]->object_value.end()) {
                    return false;
                }
            }
        }
        return arr.size() > 1;
    }
};

std::string readFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Could not open file " << filename << std::endl;
        exit(1);
    }
    return std::string((std::istreambuf_iterator<char>(file)),
                       std::istreambuf_iterator<char>());
}

std::string readStdin() {
    std::cout << "Reading from stdin..." << std::flush;
    return std::string((std::istreambuf_iterator<char>(std::cin)),
                       std::istreambuf_iterator<char>());
}

int main(int argc, char* argv[]) {
    bool fullscreen = false;
    std::string filename;
    bool show_help = false;
    bool show_version = false;
    bool show_keys = false;

    // Parse arguments
    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];
        if (arg == "--help" || arg == "-h") {
            show_help = true;
        } else if (arg == "--version" || arg == "-v") {
            show_version = true;
        } else if (arg == "--keybinding" || arg == "-k" || arg == "--key") {
            show_keys = true;
        } else if (arg == "--fullscreen" || arg == "-f") {
            fullscreen = true;
        } else if (arg[0] != '-') {
            filename = arg;
        }
    }

    if (show_version) {
        std::cout << "1.4.1" << std::endl;
        return 0;
    }

    if (show_help) {
        std::cout << "  json-tui {OPTIONS} [file]\n\n"
                  << "    A JSON terminal UI\n\n"
                  << "  OPTIONS:\n\n"
                  << "      file                              A JSON file. Omit to read from stdin.\n"
                  << "      -h, --help                        Display this help menu.\n"
                  << "      -v, --version                     Print version.\n"
                  << "      -k, --key, --keybinding           Display key binding.\n"
                  << "      -f, --fullscreen                  Display the JSON in fullscreen, in an\n"
                  << "                                        alternate buffer\n"
                  << "      \"--\" can be used to terminate flag options and force all following\n"
                  << "      arguments to be treated as positional options\n\n"
                  << "    If no file is given, json-tui reads JSON from the standard input\n"
                  << "    Please report bugs to:https://github.com/ArthurSonzogni/json-tui/issues\n";
        return 0;
    }

    if (show_keys) {
        std::cout << "┌───────────┬────────────────┐\n"
                  << "│" << COLOR_BLUE << COLOR_RESET << BG_RESET << "keys" << COLOR_RESET << BG_RESET << "       │" << COLOR_BLUE << COLOR_RESET << BG_RESET << "action" << COLOR_RESET << BG_RESET << "          │\n"
                  << "├───────────┼────────────────┤\n"
                  << "│Navigate   │← ↑ ↓ →         │\n"
                  << "│           │h j k l         │\n"
                  << "│           │Mouse::WheelUp  │\n"
                  << "│           │Mouse::WheelDown│\n"
                  << "├───────────┼────────────────┤\n"
                  << "│Toggle     │enter           │\n"
                  << "│           │Mouse::Left     │\n"
                  << "├───────────┼────────────────┤\n"
                  << "│Deep       │                │\n"
                  << "│ - Expand  │+               │\n"
                  << "│ - Collapse│-               │\n"
                  << "├───────────┼────────────────┤\n"
                  << "│Exit       │Escape          │\n"
                  << "│           │q               │\n"
                  << "├───────────┼────────────────┤\n"
                  << "│Navigate   │                │\n"
                  << "│ - first   │page-up         │\n"
                  << "│ - last    │page-down       │\n"
                  << "│ - top     │gg              │\n"
                  << "│ - bottom  │G               │\n"
                  << "└───────────┴────────────────┘ \n";
        return 0;
    }

    // Read JSON
    std::string json_str;
    if (filename.empty()) {
        json_str = readStdin();
    } else {
        json_str = readFile(filename);
