#define COLOR_BLUE "\033[94m"
#define COLOR_GREEN "\033[92m"
#define COLOR_CYAN "\033[96m"
#define COLOR_YELLOW "\033[93m"
#define COLOR_RED "\033[91m"
#define COLOR_BOLD "\033[1m"
#define COLOR_UNBOLD "\033[22m"
#define COLOR_DIM "\033[90m"
#define COLOR_RESET "\033[39m"
#define BG_RESET "\033[49m"

// Terminal control
#define TERM_DISABLE_LINE_WRAP "\033[?7l"
#define TERM_ENABLE_MOUSE_1000 "\033[?1000h"
#define TERM_ENABLE_MOUSE_1003 "\033[?1003h"
#define TERM_ENABLE_MOUSE_1015 "\033[?1015h"
#define TERM_ENABLE_MOUSE_1006 "\033[?1006h"
#define TERM_CLEAR_LINE "\033[2K"
