class ParseException : public std::runtime_error {
public:
    ParseException(const std::string& msg, size_t pos, const std::string& input) 
        : std::runtime_error(msg), pos_(pos), input_(input) {
        // Calculate line and column
        line_ = 1;
        col_ = 1;
        for (size_t i = 0; i < pos && i < input.size(); i++) {
            if (input[i] == '\n') {
                line_++;
                col_ = 1;
            } else {
                col_++;
            }
        }
    }

    size_t getLine() const { return line_; }
    size_t getCol() const { return col_; }
    std::string formatMessage() const {
        std::stringstream ss;
        ss << "[json.exception.parse_error.101] parse error at line " << line_ 
           << ", column " << col_ << ": " << what();
        return ss.str();
    }

private:
    size_t line_;
    size_t col_;
    size_t pos_;
    std::string input_;
};

// Simple JSON parser
class JsonParser {
public:
    std::shared_ptr<JsonValue> parse(const std::string& json_str) {
        pos = 0;
        input = json_str;
        try {
            return parseValue();
        } catch (const ParseException&) {
            throw;
        } catch (...) {
            throw ParseException("Invalid JSON", pos, input);
        }
    }

private:
    std::string input;
    size_t pos = 0;

    void skipWhitespace() {
        while (pos < input.size() && std::isspace(input[pos])) {
            pos++;
        }
    }

    char peek() {
        skipWhitespace();
        if (pos >= input.size()) return '\0';
        return input[pos];
    }

    char consume() {
        skipWhitespace();
        if (pos >= input.size()) return '\0';
        return input[pos++];
    }

    std::shared_ptr<JsonValue> parseValue() {
        auto val = std::make_shared<JsonValue>();
        char c = peek();

        if (c == 'n') {
            // null
            if (input.substr(pos, 4) != "null") {
                throw ParseException("syntax error while parsing value - invalid literal", pos, input);
            }
            pos += 4;
            val->type = JsonType::Null;
        } else if (c == 't') {
            // true
            if (input.substr(pos, 4) != "true") {
                throw ParseException("syntax error while parsing value - invalid literal", pos, input);
            }
            pos += 4;
            val->bool_value = true;
            val->type = JsonType::Bool;
        } else if (c == 'f') {
            // false
            if (input.substr(pos, 5) != "false") {
                throw ParseException("syntax error while parsing value - invalid literal", pos, input);
            }
            pos += 5;
            val->bool_value = false;
            val->type = JsonType::Bool;
        } else if (c == '"') {
            // string
            val->string_value = parseString();
            val->type = JsonType::String;
        } else if (c == '[') {
            // array
            val->type = JsonType::Array;
            consume(); // [
            skipWhitespace();
            if (peek() != ']') {
                while (true) {
                    val->array_value.push_back(parseValue());
                    skipWhitespace();
                    if (peek() == ']') break;
                    if (peek() != ',') {
                        throw ParseException("syntax error - expected ',' or ']'", pos, input);
                    }
                    consume(); // comma
                }
            }
            if (peek() != ']') {
                throw ParseException("syntax error - expected ']'", pos, input);
            }
            consume(); // ]
        } else if (c == '{') {
            // object
            val->type = JsonType::Object;
            consume(); // {
            skipWhitespace();
            if (peek() != '}') {
                while (true) {
                    if (peek() != '"') {
                        throw ParseException("syntax error while parsing object key - invalid literal", pos, input);
                    }
                    std::string key = parseString();
                    if (peek() != ':') {
                        throw ParseException("syntax error - expected ':'", pos, input);
                    }
                    consume(); // :
                    auto value = parseValue();
                    val->object_value[key] = value;
                    skipWhitespace();
                    if (peek() == '}') break;
                    if (peek() != ',') {
                        throw ParseException("syntax error - expected ',' or '}'", pos, input);
                    }
                    consume(); // comma
                }
            }
            if (peek() != '}') {
                throw ParseException("syntax error - expected '}'", pos, input);
            }
            consume(); // }
        } else if (c == '-' || std::isdigit(c)) {
            // number
            val->type = JsonType::Number;
            val->number_value = parseNumber();
        } else {
            throw ParseException("syntax error while parsing value - invalid literal", pos, input);
        }

        return val;
    }

    std::string parseString() {
        if (peek() != '"') {
            throw ParseException("syntax error - expected '\"'", pos, input);
        }
        consume(); // opening quote
        std::string result;
        while (pos < input.size() && input[pos] != '"') {
            if (input[pos] == '\\') {
                pos++;
                if (pos >= input.size()) {
                    throw ParseException("syntax error in string - unexpected end of input", pos, input);
                }
                switch (input[pos]) {
                    case 'n': result += '\n'; break;
                    case 't': result += '\t'; break;
                    case 'r': result += '\r'; break;
                    case '"': result += '"'; break;
                    case '\\': result += '\\'; break;
                    case '/': result += '/'; break;
                    case 'b': result += '\b'; break;
                    case 'f': result += '\f'; break;
                    case 'u': {
                        // Unicode escape - just store it as is for now
                        pos++;
                        std::string hex;
                        for (int i = 0; i < 4 && pos < input.size(); i++) {
                            hex += input[pos++];
                        }
                        // Convert hex to UTF-8 or just store escaped version
                        uint32_t codepoint = std::stoul(hex, nullptr, 16);
                        if (codepoint < 0x80) {
                            result += (char)codepoint;
                        } else if (codepoint < 0x800) {
                            result += (char)(0xC0 | (codepoint >> 6));
                            result += (char)(0x80 | (codepoint & 0x3F));
                        } else if (codepoint < 0x10000) {
                            result += (char)(0xE0 | (codepoint >> 12));
                            result += (char)(0x80 | ((codepoint >> 6) & 0x3F));
                            result += (char)(0x80 | (codepoint & 0x3F));
                        }
                        pos--;
                        break;
                    }
                    default: result += input[pos]; break;
                }
                pos++;
            } else {
                result += input[pos++];
            }
        }
        if (pos >= input.size()) {
            throw ParseException("syntax error in string - unexpected end of input", pos, input);
        }
        pos++; // closing quote
        return result;
    }

    double parseNumber() {
        size_t start = pos;
        if (input[pos] == '-') pos++;
        if (pos >= input.size() || !std::isdigit(input[pos])) {
            throw ParseException("syntax error in number - invalid digit", pos, input);
        }
        while (pos < input.size() && std::isdigit(input[pos])) pos++;
        if (pos < input.size() && input[pos] == '.') {
            pos++;
            if (pos >= input.size() || !std::isdigit(input[pos])) {
                throw ParseException("syntax error in number - invalid decimal", pos, input);
            }
            while (pos < input.size() && std::isdigit(input[pos])) pos++;
        }
        if (pos < input.size() && (input[pos] == 'e' || input[pos] == 'E')) {
            pos++;
            if (pos < input.size() && (input[pos] == '+' || input[pos] == '-')) pos++;
            if (pos >= input.size() || !std::isdigit(input[pos])) {
                throw ParseException("syntax error in number - invalid exponent", pos, input);
            }
            while (pos < input.size() && std::isdigit(input[pos])) pos++;
        }
        return std::stod(input.substr(start, pos - start));
    }
};

class JsonRenderer {
public:
    void render(const std::shared_ptr<JsonValue>& value, int term_width = 80) {
        term_width_ = term_width;
        current_line = "";
        indent_level = 0;
        output_lines.clear();
        renderValue(value, 0, false);
    }

    void printOutput(bool use_fullscreen) {
        // Output the JSON with proper formatting
        for (size_t i = 0; i < output_lines.size(); i++) {
            std::string line = output_lines[i];

            // Pad the line to terminal width
            int visible_len = 0;
            int j = 0;
            while (j < (int)line.size()) {
                if (line[j] == '\033') {
                    // Skip ANSI escape sequence
                    while (j < (int)line.size() && line[j] != 'm') {
                        j++;
                    }
                    j++;
                } else {
                    visible_len++;
                    j++;
                }
            }

            // Add padding
            line += std::string(term_width_ - visible_len, ' ');
            std::cout << line << "\r\n";
        }
    }

    int getOutputLines() { return output_lines.size(); }

private:
    std::vector<std::string> output_lines;
    std::string current_line;
    int indent_level = 0;
    int term_width_ = 80;

    std::string getIndent(int level) {
        return std::string(level * 2, ' ');
    }

    void addLine() {
        output_lines.push_back(current_line);
        current_line = "";
    }

    void renderValue(const std::shared_ptr<JsonValue>& val, int depth, bool in_array) {
        if (!val) return;

        switch (val->type) {
            case JsonType::Null:
                current_line += std::string(COLOR_RED) + BG_RESET + "null" + COLOR_RESET + BG_RESET;
                break;
            case JsonType::Bool:
                if (val->bool_value) {
                    current_line += std::string(COLOR_YELLOW) + BG_RESET + "true" + COLOR_RESET + BG_RESET;
                } else {
                    current_line += std::string(COLOR_YELLOW) + BG_RESET + "false" + COLOR_RESET + BG_RESET;
                }
                break;
            case JsonType::Number: {
                char buf[64];
                double v = val->number_value;

                // Check if it's an integer
                if (std::floor(v) == v && v >= -9007199254740992.0 && v <= 9007199254740992.0) {
                    snprintf(buf, sizeof(buf), "%.0f", v);
                } else {
                    snprintf(buf, sizeof(buf), "%g", v);
                }
                current_line += std::string(COLOR_CYAN) + BG_RESET + buf + COLOR_RESET + BG_RESET;
                break;
            }
            case JsonType::String:
                current_line += std::string(COLOR_GREEN) + BG_RESET + "\"" + val->string_value + "\"" + COLOR_RESET + BG_RESET;
                break;
            case JsonType::Array:
                renderArray(val, depth);
                break;
            case JsonType::Object:
                renderObject(val, depth);
                break;
        }
    }

    void renderArray(const std::shared_ptr<JsonValue>& val, int depth) {
        if (val->array_value.empty()) {
            current_line += "[]";
            return;
        }

        // Check if this is a table
        bool is_table = isTable(val->array_value);

        current_line += std::string(COLOR_BOLD) + "[" + COLOR_UNBOLD;
        if (is_table) {
            current_line += "   " + std::string(COLOR_DIM) + BG_RESET + "(table view)" + COLOR_RESET + BG_RESET;
        }
        addLine();

        for (size_t i = 0; i < val->array_value.size(); i++) {
            current_line = getIndent(depth + 1);
            renderValue(val->array_value[i], depth + 1, true);

            if (i < val->array_value.size() - 1) {
                current_line += ",";
            }
            addLine();
        }

        current_line = getIndent(depth) + "]";
    }

    void renderObject(const std::shared_ptr<JsonValue>& val, int depth) {
        if (val->object_value.empty()) {
            current_line += "{}";
            return;
        }

        current_line += "{";
        addLine();

        // Sort keys alphabetically
        std::vector<std::string> keys;
        for (const auto& kv : val->object_value) {
            keys.push_back(kv.first);
        }
        std::sort(keys.begin(), keys.end());

        for (size_t i = 0; i < keys.size(); i++) {
            const auto& key = keys[i];
            const auto& value = val->object_value.at(key);

            current_line = getIndent(depth + 1);
            current_line += std::string(COLOR_BLUE) + BG_RESET + "\"" + key + "\"" + COLOR_RESET + BG_RESET + ": ";

            if (value->type == JsonType::Object && !value->object_value.empty()) {
                // Collapse nested objects
                current_line += std::string(COLOR_BOLD) + "{" + COLOR_UNBOLD;
                if (depth > 0 || keys.size() > 2) {
                    current_line += "...";
                }
                current_line += std::string(COLOR_BOLD) + "}" + COLOR_UNBOLD;
            } else if (value->type == JsonType::Array && !value->array_value.empty()) {
                // Collapse arrays
                current_line += std::string(COLOR_BOLD) + "[...]" + COLOR_UNBOLD;
            } else {
                renderValue(value, depth + 1, false);
            }

            if (i < keys.size() - 1) {
                current_line += ",";
            }
            addLine();
        }

        current_line = getIndent(depth) + "}";
    }

    bool isTable(const JsonArray& arr) {
        if (arr.empty() || arr[0]->type != JsonType::Object) {
            return false;
        }

        const auto& first_obj = arr[0]->object_value;
        for (size_t i = 1; i < arr.size(); i++) {
            if (arr[i]->type != JsonType::Object) {
                return false;
            }
            if (arr[i]->object_value.size() != first_obj.size()) {
                return false;
            }
            for (const auto& kv : first_obj) {
                if (arr[i]->object_value.find(kv.first) == arr[i]->object_value.end()) {
                    return false;
                }
            }
        }
        return arr.size() > 1;
    }
};

std::string readFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Could not open file " << filename << std::endl;
        exit(1);
    }
    return std::string((std::istreambuf_iterator<char>(file)),
                       std::istreambuf_iterator<char>());
}

std::string readStdin() {
    std::cout << "Reading from stdin..." << std::flush;
    return std::string((std::istreambuf_iterator<char>(std::cin)),
                       std::istreambuf_iterator<char>());
}

