            show_version = true;
        } else if (arg == "--keybinding" || arg == "-k" || arg == "--key") {
            show_keys = true;
        } else if (arg == "--fullscreen" || arg == "-f") {
            fullscreen = true;
        } else if (arg[0] != '-') {
            filename = arg;
        }
    }

    if (show_version) {
        std::cout << "1.4.1" << std::endl;
        return 0;
    }

